import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { DatabaseSync } from "node:sqlite";

const SQLITE_PATH = resolve(process.cwd(), ".data/finance-tracker.sqlite");
const OUTPUT_PATH = resolve(process.cwd(), "migrations/0002_import_seeded_state.sql");
const KEEP_IDS = new Set(["default", "current"]);

function toSqlString(value) {
  return `'${String(value).replace(/'/g, "''")}'`;
}

function buildImportSql(rows) {
  const header = [
    "-- Generated by scripts/export-sqlite-to-d1.mjs",
    "-- Imports only persistent namespaces and excludes Playwright ephemeral data.",
    "",
  ].join("\n");

  if (!rows.length) {
    return `${header}-- No rows found for import.\n`;
  }

  const statements = rows.map((row) => {
    return [
      "INSERT INTO app_state (id, payload, updated_at)",
      `VALUES (${toSqlString(row.id)}, ${toSqlString(row.payload)}, ${toSqlString(row.updated_at)})`,
      "ON CONFLICT(id) DO UPDATE SET",
      "  payload = excluded.payload,",
      "  updated_at = excluded.updated_at;",
      "",
    ].join("\n");
  });

  return `${header}${statements.join("\n")}`;
}

const db = new DatabaseSync(SQLITE_PATH);
const rows = db
  .prepare("SELECT id, payload, updated_at FROM app_state ORDER BY id")
  .all()
  .filter((row) => KEEP_IDS.has(String(row.id)));

writeFileSync(OUTPUT_PATH, buildImportSql(rows), "utf8");
console.log(`Generated ${OUTPUT_PATH} with ${rows.length} rows.`);
